CREATE OR REPLACE FUNCTION public.can_access_recurring_finance() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','president','treasurer')) $$;
REVOKE ALL ON FUNCTION public.can_access_recurring_finance() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_access_recurring_finance() TO authenticated,service_role;
GRANT INSERT,UPDATE,DELETE ON public.recurring_expenses TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.recurring_entries FROM authenticated,anon;
DROP POLICY recurring_read ON public.recurring_expenses;
CREATE POLICY recurring_read ON public.recurring_expenses FOR SELECT TO authenticated USING(public.can_access_recurring_finance());
DROP POLICY recurring_entry_read ON public.recurring_entries;
CREATE POLICY recurring_entry_read ON public.recurring_entries FOR SELECT TO authenticated USING(public.can_access_recurring_finance());
ALTER TABLE public.recurring_entries ADD COLUMN schedule_snapshot jsonb;
UPDATE public.recurring_entries e SET schedule_snapshot=to_jsonb(s) FROM public.recurring_expenses s WHERE s.id=e.recurring_id;
CREATE FUNCTION public.snapshot_recurring_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT to_jsonb(s) INTO NEW.schedule_snapshot FROM public.recurring_expenses s WHERE s.id=NEW.recurring_id; RETURN NEW; END $$;
CREATE TRIGGER recurring_entry_snapshot BEFORE INSERT ON public.recurring_entries FOR EACH ROW EXECUTE FUNCTION public.snapshot_recurring_entry();
CREATE FUNCTION public.validate_recurring_schedule() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.end_date IS NOT NULL AND NEW.end_date<NEW.start_date THEN RAISE EXCEPTION 'End date cannot be before start date'; END IF; RETURN NEW; END $$;
CREATE TRIGGER recurring_schedule_validation BEFORE INSERT OR UPDATE ON public.recurring_expenses FOR EACH ROW EXECUTE FUNCTION public.validate_recurring_schedule();
CREATE FUNCTION public.bound_recurring_proposal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.module IN ('recurring_expenses','recurring_entries') THEN IF NOT public.can_access_recurring_finance() THEN RAISE EXCEPTION 'Authorized recurring finance access required' USING ERRCODE='42501'; END IF; IF NEW.module='recurring_entries' AND (NEW.action<>'update' OR NEW.proposed_values->>'status' IS DISTINCT FROM 'paid' OR NEW.proposed_values ? 'expected_amount') THEN RAISE EXCEPTION 'Only payment proposals are supported for monthly entries'; END IF; IF NEW.module='recurring_expenses' AND NEW.action='delete' THEN RAISE EXCEPTION 'Pause or end schedules to preserve history'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER recurring_proposal_boundary BEFORE INSERT ON public.change_proposals FOR EACH ROW EXECUTE FUNCTION public.bound_recurring_proposal();
DROP POLICY expense_attachment_read ON public.expense_attachments;
CREATE POLICY expense_attachment_read ON public.expense_attachments FOR SELECT TO authenticated USING(public.can_access_recurring_finance());
DROP POLICY expense_attachment_add ON public.expense_attachments;
CREATE POLICY expense_attachment_add ON public.expense_attachments FOR INSERT TO authenticated WITH CHECK(public.can_access_recurring_finance() AND uploaded_by=auth.uid());
CREATE FUNCTION public.validate_expense_attachment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE parent text; BEGIN IF (NEW.entry_id IS NULL)=(NEW.expense_id IS NULL) THEN RAISE EXCEPTION 'Choose exactly one expense document parent'; END IF; parent:=coalesce(NEW.entry_id,NEW.expense_id)::text; IF split_part(NEW.file_path,'/',1)<>parent OR NEW.file_size<=0 OR NEW.file_size>5242880 THEN RAISE EXCEPTION 'Invalid expense document'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='expense-documents' AND name=NEW.file_path) THEN RAISE EXCEPTION 'Upload the document before linking it'; END IF; NEW.uploaded_by:=auth.uid(); RETURN NEW; END $$;
CREATE TRIGGER expense_attachment_validation BEFORE INSERT ON public.expense_attachments FOR EACH ROW EXECUTE FUNCTION public.validate_expense_attachment();
DROP POLICY expense_document_read ON storage.objects;
CREATE POLICY expense_document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='expense-documents' AND public.can_access_recurring_finance());
DROP POLICY expense_document_add ON storage.objects;
CREATE POLICY expense_document_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='expense-documents' AND public.can_access_recurring_finance() AND (EXISTS(SELECT 1 FROM public.recurring_entries WHERE id::text=split_part(name,'/',1)) OR EXISTS(SELECT 1 FROM public.expenses WHERE id::text=split_part(name,'/',1))));
CREATE POLICY expense_document_own_staging_remove ON storage.objects FOR DELETE TO authenticated USING(bucket_id='expense-documents' AND public.can_access_recurring_finance() AND owner_id=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.expense_attachments WHERE file_path=name));
CREATE OR REPLACE FUNCTION public.expense_from_paid_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.recurring_expenses; snap jsonb; new_expense uuid; BEGIN IF OLD.status='paid' THEN IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Paid recurring entries are immutable'; END IF; RETURN NEW; END IF; IF NEW.expected_amount IS DISTINCT FROM OLD.expected_amount OR NEW.recurring_id IS DISTINCT FROM OLD.recurring_id OR NEW.period IS DISTINCT FROM OLD.period OR NEW.schedule_snapshot IS DISTINCT FROM OLD.schedule_snapshot THEN RAISE EXCEPTION 'Generated entry history is immutable'; END IF; IF NEW.status='paid' THEN IF NOT public.has_permission('finance.write') THEN RAISE EXCEPTION 'President approval or authorized finance write required' USING ERRCODE='42501'; END IF; IF NEW.actual_amount IS NULL OR NEW.actual_amount<=0 OR NEW.paid_on IS NULL OR NEW.method IS NULL OR NEW.method NOT IN ('cash','online') THEN RAISE EXCEPTION 'Enter actual amount, payment date and method'; END IF; IF NEW.actual_amount<>OLD.expected_amount AND trim(coalesce(NEW.notes,''))='' THEN RAISE EXCEPTION 'Explain the difference from the expected amount'; END IF; SELECT * INTO s FROM public.recurring_expenses WHERE id=NEW.recurring_id; snap:=coalesce(OLD.schedule_snapshot,to_jsonb(s)); IF coalesce((snap->>'requires_receipt')::boolean,false) AND NOT EXISTS(SELECT 1 FROM public.expense_attachments a JOIN storage.objects o ON o.bucket_id='expense-documents' AND o.name=a.file_path WHERE a.entry_id=NEW.id) THEN RAISE EXCEPTION 'Attach the required bill or receipt before payment approval'; END IF; INSERT INTO public.expenses(expense_date,expense_month,category,description,amount,paid_by,method,notes,recorded_by) VALUES(NEW.paid_on,NEW.period,snap->>'category',snap->>'name',NEW.actual_amount,coalesce(nullif(snap->>'vendor',''),'Committee'),NEW.method,concat_ws(E'\n',NEW.notes,nullif('Payment reference: '||NEW.payment_reference,'Payment reference: ')),auth.uid()) RETURNING id INTO new_expense; NEW.expense_id:=new_expense; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TABLE public.recurring_expense_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),schedule_id uuid,entry_id uuid,actor_id uuid,event text NOT NULL,previous_values jsonb,new_values jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.recurring_expense_events TO authenticated;
GRANT ALL ON public.recurring_expense_events TO service_role;
ALTER TABLE public.recurring_expense_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY recurring_events_read ON public.recurring_expense_events FOR SELECT TO authenticated USING(public.can_access_recurring_finance());
CREATE FUNCTION public.audit_recurring_expense() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.recurring_expense_events(schedule_id,entry_id,actor_id,event,previous_values,new_values) VALUES(CASE WHEN TG_TABLE_NAME='recurring_expenses' THEN NEW.id ELSE NEW.recurring_id END,CASE WHEN TG_TABLE_NAME='recurring_entries' THEN NEW.id ELSE NULL END,auth.uid(),TG_TABLE_NAME||':'||lower(TG_OP),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER recurring_schedule_audit AFTER INSERT OR UPDATE ON public.recurring_expenses FOR EACH ROW EXECUTE FUNCTION public.audit_recurring_expense();
CREATE TRIGGER recurring_entry_audit AFTER INSERT OR UPDATE ON public.recurring_entries FOR EACH ROW EXECUTE FUNCTION public.audit_recurring_expense();
CREATE FUNCTION public.recurring_pending_entries() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT record_key::uuid FROM public.change_proposals WHERE module='recurring_entries' AND status='pending' AND public.can_access_recurring_finance() $$;
REVOKE ALL ON FUNCTION public.recurring_pending_entries() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.recurring_pending_entries() TO authenticated;
CREATE POLICY recurring_treasurer_audit_read ON public.change_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'treasurer') AND EXISTS(SELECT 1 FROM public.change_proposals p WHERE p.id=proposal_id AND p.submitted_by=auth.uid() AND p.module IN ('recurring_expenses','recurring_entries','expenses')));